// Supplemental UI-only adapter. Not an authentication, persistence or backup proof.
import {createRoot} from 'react-dom/client';
import {ExpenseEditor} from '../../src/app/expenses/expense-editor';
import type {createExpenseClient,ExpenseContext} from '../../src/client/expenses';
import type {ExpenseRevision} from '../../src/bookkeeping/expenses/expense-contract';
import type {createReceiptClient} from '../../src/client/expense-receipts';
import {pendingReceipt} from '../../src/client/pending-receipt';
import type {PendingReceipt} from '../../src/client/pending-receipt';
import type {ReceiptView} from '../../src/bookkeeping/expenses/receipt-contract';
const businessId='11111111-1111-1111-1111-111111111111',epoch='22222222-2222-2222-2222-222222222222',actorId='33333333-3333-3333-3333-333333333333';
const rows:ExpenseRevision[]=[];let loseReply=true,historyReads=0;
const context:ExpenseContext={businessId,recoveryEpoch:epoch,writeState:'ready',binding:'A'.repeat(43)};
const client:ReturnType<typeof createExpenseClient>={async lookup(_context,reference){const expense=rows.find(row=>row.operationId===reference.operationId&&row.expenseId===reference.expenseId&&BigInt(row.revision)===BigInt(reference.expectedRevision)+1n);return expense?{state:'committed',expense}:{state:'absent'};},async context(){return context;},async history(){historyReads++;if(historyReads>1&&!rows.some(r=>r.expenseId==='bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb'))rows.push({businessId,expenseId:'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb',revision:'1',operationId:'cccccccc-cccc-cccc-cccc-cccccccccccc',actorId,recordedAt:'2026-10-28T23:30:00.000000Z',payload:{...rows[0]!.payload,description:'Synthetic other-device expense',amountCents:'2399',voided:false,changeReason:null}});return rows;},async save(_context,request){let row=rows.find(r=>r.operationId===request.operationId);if(!row){row={businessId,expenseId:request.expenseId,revision:(BigInt(request.expectedRevision)+1n).toString(),operationId:request.operationId,actorId,recordedAt:'2026-10-28T23:00:00.000000Z',payload:request.payload};rows.push(row);}if(loseReply){loseReply=false;throw new Error('Synthetic lost response');}return {state:'committed',expense:row};}};
const receipts:ReceiptView[]=[];let loseReceiptReply=true,loseResumeReply=true,receiptOriginal:PendingReceipt|null=null;
const receiptClient:ReturnType<typeof createReceiptClient>={pending(){return receiptOriginal;},async recover(){if(!receiptOriginal)return {state:"none"};const original=receiptOriginal,receipt=receipts.find(r=>r.receiptId===original.reference.receiptId);if(!receipt) return {state:"absent"};receiptOriginal=null;return {state:"committed",original,receipt};},async lookup(){return {state:"absent"};},async list(_context,expenseId){if(!receipts.some(r=>r.receiptId==='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'))receipts.push({receiptId:'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',expenseId,expenseRevision:'1',receiptVersion:'1',status:'reserved',declaredType:'image/png',byteSize:4,sourceSha256:null});return receipts;},async attach(attempt){let receipt=receipts.find(r=>r.receiptId===attempt.receiptId);if(!receipt){receipt={receiptId:attempt.receiptId,expenseId:attempt.expenseId,expenseRevision:attempt.expenseRevision,receiptVersion:'2',status:'available',declaredType:'image/png',byteSize:attempt.file.size,sourceSha256:'a'.repeat(64)};receipts.push(receipt);}if(loseReceiptReply){receiptOriginal=pendingReceipt({schemaVersion:1,businessId,binding:context.binding,reference:{operationId:attempt.publishOperationId,recoveryEpoch:epoch,receiptId:attempt.receiptId,expenseId:attempt.expenseId,expenseRevision:attempt.expenseRevision,expectedRevision:'1'}});loseReceiptReply=false;throw new Error('Synthetic lost receipt reply');}return receipt;},async resume(_context,r,operationId){const saved={...r,receiptVersion:'2' as const,status:'available' as const,sourceSha256:'a'.repeat(64)},index=receipts.findIndex(row=>row.receiptId===r.receiptId);if(index<0)throw new Error();receipts[index]=saved;if(loseResumeReply){receiptOriginal=pendingReceipt({schemaVersion:1,businessId,binding:context.binding,reference:{operationId,recoveryEpoch:epoch,receiptId:r.receiptId,expenseId:r.expenseId,expenseRevision:r.expenseRevision,expectedRevision:'1'}});loseResumeReply=false;throw new Error('Synthetic lost resume reply');}return saved;},async download(_context,r,variant){return {blob:new Blob(['Synthetic UI-only receipt download'],{type:'image/png'}),name:`receipt-${r.receiptId}${variant==='preview'?'-preview':''}.png`};}};
createRoot(document.getElementById('root')!).render(<main><ExpenseEditor client={client} receiptClient={receiptClient}/></main>);
